async function submitDeliveryQuote(orderId,action,fee){
 const {data:{session}}=await supabase.auth.getSession();if(!session?.access_token){toast('Please sign in again.');return}
 const response=await fetch(SUPABASE_URL+'/functions/v1/confirm-delivery-quote',{method:'POST',headers:{'Content-Type':'application/json',apikey:SUPABASE_KEY,Authorization:'Bearer '+session.access_token},body:JSON.stringify({order_id:orderId,action,delivery_fee:fee})});
 const result=await response.json();if(!response.ok)throw new Error(result.error||'Delivery quote update failed');
 toast(action==='unavailable'?'Order marked as unavailable for delivery.':'Delivery fee confirmed. Customer can now pay the updated total.');
 await loadDeliveryQuoteAdmin();await loadDispatchAdmin();await renderAdmin();
}
$('#deliveryQuoteQueue').addEventListener('submit',async e=>{
 const form=e.target.closest('.delivery-quote-form');if(!form)return;e.preventDefault();if(!isAdmin())return;
 const fee=Number(new FormData(form).get('delivery_fee'));if(!Number.isFinite(fee)||fee<0){toast('Enter a valid delivery fee.');return}
 const btn=form.querySelector('button[type="submit"]');btn.disabled=true;try{await submitDeliveryQuote(form.dataset.quoteOrder,'confirm',fee)}catch(err){toast(err.message)}finally{btn.disabled=false}
});
$('#deliveryQuoteQueue').addEventListener('click',async e=>{
 const btn=e.target.closest('[data-quote-unavailable]');if(!btn||!isAdmin())return;
 if(!confirm('Mark this order as unavailable for delivery?'))return;btn.disabled=true;
 try{await submitDeliveryQuote(btn.dataset.quoteUnavailable,'unavailable')}catch(err){toast(err.message)}finally{btn.disabled=false}
});
async function loadDispatchAdmin(){
 if(!isAdmin())return;
 await loadDeliveryQuoteAdmin();
 const box=$('#dispatchOrders'),select=$('#dispatchOrderSelect');box.textContent='Loading orders…';
 const {data,error}=await supabase.from('orders').select('id,order_number,customer_name,phone,delivery_address,delivery_city,delivery_region,delivery_country_code,fulfilment_method,delivery_status,tracking_reference,estimated_delivery_date,created_at').order('created_at',{ascending:false}).limit(100);
 if(error){box.textContent='Could not load orders: '+error.message;return}
 const rows=data||[];
 select.innerHTML='<option value="">Choose an order</option>'+rows.map(o=>'<option value="'+o.id+'">'+esc(o.order_number)+' — '+esc(o.customer_name||'Customer')+'</option>').join('');
 box.innerHTML=rows.map(o=>'<article class="admin-row"><b>'+esc(o.order_number)+'</b> · '+esc(o.customer_name||'Customer')+'<br><span class="muted">'+esc(o.phone||'')+' · '+esc([o.delivery_city,o.delivery_region,o.delivery_country_code].filter(Boolean).join(', ')||o.delivery_address||'Destination pending')+'</span><br><span class="pill">'+esc(o.delivery_status||'pending_confirmation')+'</span> · '+esc(o.tracking_reference||'No tracking reference')+'<br><span class="muted">Method: '+esc(o.fulfilment_method||'delivery')+' · ETA: '+esc(o.estimated_delivery_date||'Not set')+'</span></article>').join('')||'<p class="muted">No orders available.</p>';
}
$('#deliveryZoneForm').addEventListener('submit',async e=>{
 e.preventDefault();if(!isAdmin())return;const f=new FormData(e.currentTarget),id=String(f.get('id')||'').trim();
 const payload={zone_name:String(f.get('zone_name')||'').trim(),country_name:String(f.get('country_name')||'').trim(),country_code:String(f.get('country_code')||'').trim().toUpperCase(),region:String(f.get('region')||'').trim()||null,city:String(f.get('city')||'').trim()||null,postal_code_prefix:String(f.get('postal_code_prefix')||'').trim()||null,currency:String(f.get('currency')||'').trim().toUpperCase(),delivery_fee:Number(f.get('delivery_fee')),estimated_min_days:f.get('estimated_min_days')===''?null:Number(f.get('estimated_min_days')),estimated_max_days:f.get('estimated_max_days')===''?null:Number(f.get('estimated_max_days')),service_status:String(f.get('service_status')),is_active:f.get('is_active')==='on'};
 if(!/^[A-Z]{2}$/.test(payload.country_code)||!/^[A-Z]{3}$/.test(payload.currency)||!Number.isFinite(payload.delivery_fee)||payload.delivery_fee<0||[payload.estimated_min_days,payload.estimated_max_days].some(n=>n!==null&&(!Number.isInteger(n)||n<0))||(payload.estimated_min_days!==null&&payload.estimated_max_days!==null&&payload.estimated_max_days<payload.estimated_min_days)){toast('Check country, currency, fee and delivery day values.');return}
 const btn=$('#deliveryZoneSave');btn.disabled=true;try{const query=id?supabase.from('delivery_zones').update(payload).eq('id',id):supabase.from('delivery_zones').insert(payload);const {error}=await query;if(error)throw error;toast('Delivery zone saved.');clearDeliveryZoneForm();await loadDeliveryZonesAdmin()}catch(err){toast('Delivery zone was not saved: '+err.message)}finally{btn.disabled=false}
});
$('#deliveryZoneCancel').addEventListener('click',clearDeliveryZoneForm);
$('#deliveryZonesAdmin').addEventListener('click',async e=>{
 if(!isAdmin())return;const edit=e.target.closest('[data-zone-edit]'),toggle=e.target.closest('[data-zone-toggle]');if(!edit&&!toggle)return;
 if(edit){const {data,error}=await supabase.from('delivery_zones').select('*').eq('id',edit.dataset.zoneEdit).single();if(error){toast(error.message);return}const form=$('#deliveryZoneForm');Object.entries(data).forEach(([k,v])=>{if(form.elements[k]){if(form.elements[k].type==='checkbox')form.elements[k].checked=!!v;else form.elements[k].value=v??''}});$('#deliveryZoneSave').textContent='Update delivery zone';form.scrollIntoView({behavior:'smooth',block:'start'});return}
 const {error}=await supabase.from('delivery_zones').update({is_active:toggle.dataset.active==='true'}).eq('id',toggle.dataset.zoneToggle);if(error)toast('Zone status was not changed: '+error.message);else{toast('Delivery zone status updated.');await loadDeliveryZonesAdmin()}
});
$('#dispatchForm').addEventListener('submit',async e=>{
 e.preventDefault();if(!isAdmin())return;const form=e.currentTarget,f=new FormData(form),orderId=String(f.get('order_id')||''),status=String(f.get('delivery_status')||''),description=String(f.get('description')||'').trim();if(!orderId||!deliveryStatuses.includes(status)||!description){toast('Choose an order, status and update description.');return}
 const tracking_reference=String(f.get('tracking_reference')||'').trim()||null,estimated_delivery_date=String(f.get('estimated_delivery_date')||'').trim()||null,location=String(f.get('location')||'').trim()||null;
 const btn=$('#dispatchSave');btn.disabled=true;try{
  const update={delivery_status:status,tracking_reference,estimated_delivery_date};if(['dispatched','in_transit','delivered'].includes(status))update.shipped_at=new Date().toISOString();if(status==='delivered')update.delivered_at=new Date().toISOString();
  const {error:updateError}=await supabase.from('orders').update(update).eq('id',orderId);if(updateError)throw updateError;
  const {error:eventError}=await supabase.from('order_fulfilment_events').insert({order_id:orderId,status,description,location,tracking_reference,created_by:user.id});if(eventError)throw eventError;
  toast('Tracking update published.');form.reset();await loadDispatchAdmin();await loadCustomerOrders()
 }catch(err){toast('Dispatch update encountered an error: '+err.message+'. Check the order status before retrying.')}finally{btn.disabled=false}
});
async function loadStage6Finance(){
 if(!isAdmin())return;
 const results=await Promise.all([
  supabase.from('delivery_partners').select('id,name,payout_currency,rate_basis,agreed_rate,payment_terms_note').order('name'),
  supabase.from('delivery_partner_earnings').select('id,delivery_partner_id,shipment_id,net_amount,status,created_at').order('created_at',{ascending:false}).limit(100),
  supabase.from('delivery_partner_settlements').select('id,delivery_partner_id,amount,status,payout_method,payout_details,payout_reference,requested_at').order('requested_at',{ascending:false}).limit(100),
  supabase.from('order_shipments').select('id,tracking_reference,orders(order_number)').eq('status','delivered').not('delivery_partner_id','is',null)
 ]);
 const partners=results[0].data||[],earnings=results[1].data||[],settlements=results[2].data||[],delivered=results[3].data||[];
 const terms=$('#stage6PartnerTerms');
 if(terms)terms.innerHTML=partners.map(p=>'<form class="stage6TermsForm admin-row" data-partner="'+p.id+'"><b>'+esc(p.name)+'</b><div class="admin-grid"><div class="field"><label>Payment basis</label><select name="rate_basis"><option value="manual" '+(p.rate_basis==='manual'?'selected':'')+'>Manual entry</option><option value="per_delivery" '+(p.rate_basis==='per_delivery'?'selected':'')+'>Agreed amount per delivery</option></select></div><div class="field"><label>Agreed amount</label><input name="agreed_rate" type="number" min="0" step="0.01" value="'+(p.agreed_rate==null?'':p.agreed_rate)+'" placeholder="No preset amount"></div><div class="field"><label>Currency</label><input name="currency" maxlength="3" value="'+esc(p.payout_currency||'NGN')+'"></div><div class="field wide"><label>Negotiated terms</label><input name="terms_note" maxlength="1000" value="'+esc(p.payment_terms_note||'')+'"></div><button class="btn small" type="submit">Save terms</button></div></form>').join('')||'<p class="muted">No partners registered.</p>';
 const sel=$('#stage6EarningShipment');
 if(sel)sel.innerHTML='<option value="">Choose delivered shipment</option>'+delivered.filter(x=>!earnings.some(y=>y.shipment_id===x.id)).map(x=>'<option value="'+x.id+'">'+esc(x.orders?.order_number||'Order')+' · '+esc(x.tracking_reference||x.id)+'</option>').join('');
 const list=$('#stage6SettlementList');
 if(list)list.innerHTML=settlements.map(x=>{const p=partners.find(y=>y.id===x.delivery_partner_id);return '<article class="admin-row"><b>'+esc(p?.name||'Partner')+'</b> · '+esc(x.amount)+' '+esc(p?.payout_currency||'')+'<br><span class="pill">'+esc(x.status)+'</span> · '+esc(x.payout_method||'')+'<p class="muted">'+esc(JSON.stringify(x.payout_details||{}))+'</p>'+(x.status==='requested'?'<button class="btn small" data-s6-decision="approve" data-id="'+x.id+'">Approve</button> <button class="btn light small" data-s6-decision="reject" data-id="'+x.id+'">Reject</button>':'')+(x.status==='approved'?'<form class="stage6PayForm" data-id="'+x.id+'"><input name="reference" placeholder="Payment reference (optional)"><button class="btn small" type="submit">Record payment</button></form>':'')+'</article>'}).join('')||'<p class="muted">No settlement requests.</p>';
}
async function loadStage4Logistics(){if(!isAdmin())return;const [partners,orders,shipments]=await Promise.all([supabase.from('delivery_partners').select('id,name,service_type,phone,coverage_city,coverage_region,is_active').order('name'),supabase.from('orders').select('id,order_number,customer_name,payment_status,fulfilment_method,delivery_region,delivery_city,delivery_status').order('created_at',{ascending:false}).limit(100),supabase.from('order_shipments').select('id,order_id,tracking_reference,status,created_at,delivery_partner_id').order('created_at',{ascending:false}).limit(100)]);const ps=partners.data||[],os=orders.data||[],ss=shipments.data||[];$('#stage4PartnerList').innerHTML=partners.error?esc(partners.error.message):ps.map(p=>'<article class="admin-row"><b>'+esc(p.name)+'</b> · '+esc(p.service_type)+'<br><span class="muted">'+esc([p.phone,p.coverage_city,p.coverage_region].filter(Boolean).join(' · '))+'</span> <span class="pill">'+(p.is_active?'Active':'Inactive')+'</span></article>').join('')||'<p class="muted">No delivery partners added yet.</p>';$('#stage4PartnerSelect').innerHTML='<option value="">Unassigned / Iyanda handling</option>'+ps.filter(p=>p.is_active).map(p=>'<option value="'+p.id+'">'+esc(p.name)+' · '+esc(p.service_type)+'</option>').join('');$('#stage4OrderSelect').innerHTML='<option value="">Choose a paid delivery order</option>'+os.filter(o=>o.fulfilment_method==='delivery'&&o.payment_status==='paid').map(o=>'<option value="'+o.id+'">'+esc(o.order_number)+' — '+esc(o.customer_name||'Customer')+' · '+esc([o.delivery_city,o.delivery_region].filter(Boolean).join(', '))+'</option>').join('');$('#stage4ShipmentList').innerHTML=shipments.error?esc(shipments.error.message):ss.map(x=>{const o=os.find(z=>z.id===x.order_id),p=ps.find(z=>z.id===x.delivery_partner_id);return '<article class="admin-row"><b>'+esc(o?.order_number||'Order')+'</b> · '+esc(p?.name||'Iyanda handling')+'<br><span class="pill">'+esc(x.status)+'</span> · '+esc(x.tracking_reference||'No tracking reference')+'</article>'}).join('')||'<p class="muted">No shipments created yet.</p>'};await loadStage6Finance()

