 if(f){e.preventDefault();if(!isAdmin())return;const v=Object.fromEntries(new FormData(f));try{const {error}=await supabase.rpc('admin_set_delivery_partner_terms',{p_partner_id:f.dataset.partner,p_rate_basis:v.rate_basis,p_agreed_rate:v.agreed_rate?Number(v.agreed_rate):null,p_currency:v.currency.toUpperCase(),p_terms_note:v.terms_note||null});if(error)throw error;toast('Partner terms saved.')}catch(err){toast('Could not save terms: '+err.message)}}
