 const partnerForm=e.target.closest('#partnerSettlementForm');
 if(partnerForm){e.preventDefault();if(!user)return;const v=Object.fromEntries(new FormData(partnerForm));try{const {error}=await supabase.rpc('partner_request_delivery_settlement',{p_payout_method:v.payout_method,p_payout_details:{details:v.payout_details}});if(error)throw error;toast('Settlement request submitted.');partnerForm.reset();await loadDeliveryPartnerPortal()}catch(err){toast('Settlement request failed: '+err.message)}}
