let dailyTab='tasks',dailyRows=[],dailyReminderSeen=new Set();
function dailyDate(v){return v?new Date(v).toLocaleString('en-NG',{dateStyle:'medium',timeStyle:'short'}):'No date set'}
function dailyTabSet(tab){dailyTab=tab;document.querySelectorAll('[data-daily-tab]').forEach(b=>b.classList.toggle('active',b.dataset.dailyTab===tab));$('#dailyFormHeading').textContent=tab==='meetings'?'Add meeting notes':'Add a task';$('#dailyTaskForm [name=category]').value=tab==='meetings'?'meeting':'task';renderDailyList()}
async function loadDailyTasks(){if(!user){$('#dailySignIn').classList.remove('hidden');$('#dailyWorkspace').classList.add('hidden');return}$('#dailySignIn').classList.add('hidden');$('#dailyWorkspace').classList.remove('hidden');const {data,error}=await supabase.from('iyanda_tasks').select('id,title,description,status,priority,due_at,reminder_at,completed_at,created_at,category').eq('user_id',user.id).order('due_at',{ascending:true,nullsFirst:false}).limit(200);if(error){toast('Daily Life could not load: '+error.message);return}dailyRows=data||[];const open=dailyRows.filter(x=>!['completed','cancelled'].includes(x.status));const today=new Date().toDateString();$('#dailyOpenCount').textContent=open.length;$('#dailyTodayCount').textContent=open.filter(x=>x.due_at&&new Date(x.due_at).toDateString()===today).length;$('#dailyDoneCount').textContent=dailyRows.filter(x=>x.status==='completed').length;renderDailyList();checkDailyReminders()}
function renderDailyList(){let rows=dailyRows.filter(x=>dailyTab==='meetings'?x.category==='meeting':x.category!=='meeting');if(dailyTab==='today')rows=rows.filter(x=>!['completed','cancelled'].includes(x.status)&&(!x.due_at||new Date(x.due_at)<=new Date(new Date().setHours(23,59,59,999))));if(dailyTab==='calendar')rows=rows.filter(x=>x.due_at);if(dailyTab==='meetings')rows=dailyRows.filter(x=>x.category==='meeting');if(dailyTab==='tasks')rows=rows.filter(x=>!['completed','cancelled'].includes(x.status));rows.sort((a,b)=>(a.due_at?new Date(a.due_at).getTime():Infinity)-(b.due_at?new Date(b.due_at).getTime():Infinity));$('#dailyList').innerHTML=rows.length?rows.map(t=>'<article class="daily-item"><div class="daily-item-top"><div><h4>'+esc(t.title)+'</h4><div class="daily-meta"><span class="pill">'+esc(t.priority)+'</span><span>'+esc(t.category==='meeting'?'Meeting':'Task')+'</span><span>'+esc(t.status.replace('_',' '))+'</span></div></div><button class="iconbtn" type="button" data-daily-delete="'+t.id+'" aria-label="Delete">✕</button></div>'+(t.description?'<p>'+esc(t.description)+'</p>':'')+'<div class="daily-meta"><span>Due: '+esc(dailyDate(t.due_at))+'</span><span>Reminder: '+esc(dailyDate(t.reminder_at))+'</span></div><div class="daily-actions"><select data-daily-status="'+t.id+'" aria-label="Task status">'+[['todo','To do'],['in_progress','In progress'],['completed','Completed'],['cancelled','Cancelled']].map(([v,l])=>'<option value="'+v+'" '+(v===t.status?'selected':'')+'>'+l+'</option>').join('')+'</select>'+(t.category==='meeting'?'<button class="btn light small" type="button" data-daily-summarize="'+t.id+'">Summarise with AI</button>':'')+'</div></article>').join(''):'<div class="daily-empty">Nothing here yet. Add a task or meeting note to get started.</div>'}
$('#dailySignInBtn').addEventListener('click',openAuth);$('#dailyRefresh').addEventListener('click',loadDailyTasks);$('#dailyTabs').addEventListener('click',e=>{const b=e.target.closest('[data-daily-tab]');if(b)dailyTabSet(b.dataset.dailyTab)});
$('#dailyTaskForm').addEventListener('submit',async e=>{e.preventDefault();if(!user){openAuth();return}const f=new FormData(e.currentTarget),payload={user_id:user.id,title:String(f.get('title')).trim(),description:String(f.get('description')||''),category:f.get('category'),priority:f.get('priority'),due_at:f.get('due_at')?new Date(f.get('due_at')).toISOString():null,reminder_at:f.get('reminder_at')?new Date(f.get('reminder_at')).toISOString():null};const b=$('#dailySaveBtn');b.disabled=true;b.textContent='Saving…';const {error}=await supabase.from('iyanda_tasks').insert(payload);b.disabled=false;b.textContent='Save task';if(error){toast('Could not save: '+error.message);return}e.currentTarget.reset();dailyTabSet(payload.category==='meeting'?'meetings':'tasks');await loadDailyTasks();toast(payload.category==='meeting'?'Meeting notes saved.':'Task saved.')});
$('#dailyList').addEventListener('change',async e=>{const id=e.target.dataset.dailyStatus;if(!id)return;const status=e.target.value;const {error}=await supabase.from('iyanda_tasks').update({status,completed_at:status==='completed'?new Date().toISOString():null,updated_at:new Date().toISOString()}).eq('id',id).eq('user_id',user.id);if(error)toast(error.message);else{toast('Task updated.');await loadDailyTasks()}});
$('#dailyList').addEventListener('click',async e=>{const del=e.target.closest('[data-daily-delete]');if(del){if(!confirm('Delete this item permanently?'))return;const {error}=await supabase.from('iyanda_tasks').delete().eq('id',del.dataset.dailyDelete).eq('user_id',user.id);if(error)toast(error.message);else{toast('Item deleted.');await loadDailyTasks()}return}const sum=e.target.closest('[data-daily-summarize]');if(sum){const t=dailyRows.find(x=>x.id===sum.dataset.dailySummarize);if(!t)return;sum.disabled=true;sum.textContent='Summarising…';try{let cid=conversationId;if(!cid){const {data,error}=await supabase.from('ai_conversations').insert({user_id:user.id,title:'Meeting summary'}).select('id').single();if(error)throw error;cid=data.id;conversationId=cid}const message='Summarise these meeting notes. List decisions, action items, owners and deadlines only when stated; do not invent details.\n\n'+t.title+'\n'+t.description;const {error:saveError}=await supabase.from('ai_messages').insert({conversation_id:cid,user_id:user.id,role:'user',content:message});if(saveError)throw saveError;const {data:{session:s}}=await supabase.auth.getSession();const response=await fetch(SUPABASE_URL+'/functions/v1/iyanda-ai',{method:'POST',headers:{'Content-Type':'application/json',apikey:SUPABASE_KEY,Authorization:'Bearer '+s.access_token},body:JSON.stringify({conversation_id:cid,message})});const result=await response.json();if(!response.ok)throw new Error(result.error||'AI summary failed');const {error:updateError}=await supabase.from('iyanda_tasks').update({description:t.description+'\n\nAI SUMMARY\n'+result.answer,updated_at:new Date().toISOString()}).eq('id',t.id).eq('user_id',user.id);if(updateError)throw updateError;await loadDailyTasks();toast('Meeting summary saved to your notes.')}catch(err){toast(err.message||'Could not summarise notes.')}finally{sum.disabled=false;sum.textContent='Summarise with AI'}}});
$('#enableTaskAlerts').addEventListener('click',async()=>{if(!('Notification'in window)){toast('Notifications are not supported in this browser.');return}const p=await Notification.requestPermission();toast(p==='granted'?'Reminders enabled while Iyanda is open.':'Notification permission was not granted.')});
function checkDailyReminders(){if(!user)return;const now=Date.now();dailyRows.filter(t=>t.reminder_at&&t.status!=='completed'&&t.status!=='cancelled'&&new Date(t.reminder_at).getTime()<=now&&!dailyReminderSeen.has(t.id)).forEach(t=>{dailyReminderSeen.add(t.id);toast('Reminder: '+t.title);if('Notification'in window&&Notification.permission==='granted')new Notification('Iyanda reminder',{body:t.title})})}
setInterval(checkDailyReminders,60000);


/* Iyanda My Workspace */
let workspaceFiles=[],workspaceSelected=null,workspaceLastAnswer='';
function workspaceSize(n){return n<1024*1024?(n/1024).toFixed(0)+' KB':(n/1024/1024).toFixed(1)+' MB'}
function workspaceExt(n){return (n.split('.').pop()||'').toLowerCase()}
async function workspaceExtract(file){
 const ext=workspaceExt(file.name);
 if(ext==='txt'||ext==='csv')return await file.text();
 if(ext==='pdf'){const pdfjs=await import('https://esm.sh/pdfjs-dist@4.4.168/legacy/build/pdf.mjs');const pdf=await pdfjs.getDocument({data:await file.arrayBuffer()}).promise;let out=[];for(let p=1;p<=Math.min(pdf.numPages,80);p++){const page=await pdf.getPage(p);const c=await page.getTextContent();out.push(c.items.map(x=>x.str).join(' '))}return out.join('\n\n')}
 if(ext==='docx'){const mammoth=await import('https://esm.sh/mammoth@1.8.0');const r=await mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});return r.value}
 if(ext==='xlsx'||ext==='xls'){const XLSX=await import('https://esm.sh/xlsx@0.18.5');const wb=XLSX.read(await file.arrayBuffer(),{type:'array'});return wb.SheetNames.map(n=>'SHEET: '+n+'\n'+XLSX.utils.sheet_to_csv(wb.Sheets[n])).join('\n\n')}
 if(ext==='doc')return '';
 return '';
}
async function workspaceLoad(){if(!user){$('#workspaceSignIn').classList.remove('hidden');$('#workspaceMain').classList.add('hidden');return}$('#workspaceSignIn').classList.add('hidden');$('#workspaceMain').classList.remove('hidden');const {data,error}=await supabase.from('iyanda_workspace_files').select('id,file_name,mime_type,file_size,storage_path,ai_summary,created_at,source_provider').eq('user_id',user.id).order('created_at',{ascending:false}).limit(100);if(error){toast('Workspace could not load: '+error.message);return}workspaceFiles=data||[];workspaceRender()}
function workspaceRender(){$('#workspaceFiles').innerHTML=workspaceFiles.length?workspaceFiles.map(f=>'<div class="workspace-file"><div><b>'+esc(f.file_name)+'</b><small>'+workspaceSize(f.file_size)+' · '+new Date(f.created_at).toLocaleDateString()+(f.ai_summary?' · Summary saved':'')+'</small></div><div class="workspace-actions"><button class="btn light small" type="button" data-ws-select="'+f.id+'">Open</button><button class="btn light small" type="button" data-ws-download="'+f.id+'">Download</button><button class="iconbtn" type="button" data-ws-delete="'+f.id+'">Delete</button></div></div>').join(''):'<div class="daily-empty">No files yet. Upload your first document.</div>'}
$('#workspaceSignInBtn').addEventListener('click',openAuth);
$('#workspaceRefresh').addEventListener('click',workspaceLoad);
$('#workspaceUpload').addEventListener('change',async e=>{if(!user){openAuth();return}const files=[...e.target.files];for(const file of files){if(file.size>25*1024*1024){toast(file.name+' exceeds the 25 MB limit.');continue}const ext=workspaceExt(file.name);if(!['pdf','doc','docx','xls','xlsx','pptx','csv','txt'].includes(ext)){toast('Unsupported file: '+file.name);continue}toast('Preparing '+file.name+'…');let extracted='';try{extracted=await workspaceExtract(file)}catch(err){console.warn('Text extraction:',err);toast('Uploaded, but text extraction failed for '+file.name)}const safeName=file.name.replace(/[^a-zA-Z0-9._-]/g,'_');const path=user.id+'/'+crypto.randomUUID()+'-'+safeName;const {error:upErr}=await supabase.storage.from('iyanda-workspace').upload(path,file,{contentType:file.type||'application/octet-stream',upsert:false});if(upErr){toast('Upload failed: '+upErr.message);continue}const {data,error}=await supabase.from('iyanda_workspace_files').insert({user_id:user.id,file_name:file.name,mime_type:file.type||'application/octet-stream',file_size:file.size,storage_path:path,extracted_text:extracted}).select('id').single();if(error){await supabase.storage.from('iyanda-workspace').remove([path]);toast('Could not save file record: '+error.message);continue}toast('Uploaded '+file.name)}e.target.value='';await workspaceLoad()});
$('#workspaceFiles').addEventListener('click',async e=>{const open=e.target.closest('[data-ws-select]');if(open){workspaceSelected=workspaceFiles.find(f=>f.id===open.dataset.wsSelect);if(!workspaceSelected)return;$('#workspaceSelected').innerHTML='<b>'+esc(workspaceSelected.file_name)+'</b><p class="muted">'+workspaceSize(workspaceSelected.file_size)+' · '+esc(workspaceSelected.mime_type)+'</p>'+(workspaceSelected.ai_summary?'<p>'+esc(workspaceSelected.ai_summary)+'</p>':'');$('#workspacePrompt').focus();return}const dl=e.target.closest('[data-ws-download]');if(dl){const f=workspaceFiles.find(x=>x.id===dl.dataset.wsDownload);if(!f)return;const {data,error}=await supabase.storage.from('iyanda-workspace').createSignedUrl(f.storage_path,60);if(error){toast(error.message);return}window.open(data.signedUrl,'_blank','noopener');return}const del=e.target.closest('[data-ws-delete]');if(del){if(!confirm('Permanently delete this file from your workspace?'))return;const f=workspaceFiles.find(x=>x.id===del.dataset.wsDelete);if(!f)return;const {error}=await supabase.storage.from('iyanda-workspace').remove([f.storage_path]);if(error){toast(error.message);return}const {error:de}=await supabase.from('iyanda_workspace_files').delete().eq('id',f.id).eq('user_id',user.id);if(de){toast(de.message);return}workspaceSelected=null;$('#workspaceSelected').textContent='Select a file from your workspace.';await workspaceLoad();toast('File deleted.')}});
$('#workspaceAnalyse').addEventListener('click',async()=>{if(!user){openAuth();return}if(!workspaceSelected){toast('Select a file first.');return}const f=workspaceSelected;const prompt=$('#workspacePrompt').value.trim()||'Summarise this document. Extract key facts, decisions, risks and action points. Do not invent missing details.';const {data:{session:s}}=await supabase.auth.getSession();if(!s){openAuth();return}const btn=$('#workspaceAnalyse');btn.disabled=true;btn.textContent='Analysing…';$('#workspaceAnswer').style.display='block';$('#workspaceAnswer').textContent='Iyanda AI is reading the extracted document text…';try{const {data,error}=await supabase.from('ai_conversations').insert({user_id:user.id,title:'Workspace: '+f.file_name.slice(0,80)}).select('id').single();if(error)throw error;const textContent=f.extracted_text||'No machine-readable text could be extracted. Ask the user to upload a text-based PDF, DOCX, XLSX, CSV or TXT version.';const message=prompt+'\n\nDOCUMENT: '+f.file_name+'\n\nDOCUMENT CONTENT (may be incomplete):\n'+textContent.slice(0,45000);const {error:me}=await supabase.from('ai_messages').insert({conversation_id:data.id,user_id:user.id,role:'user',content:message});if(me)throw me;const response=await fetch(SUPABASE_URL+'/functions/v1/iyanda-ai',{method:'POST',headers:{'Content-Type':'application/json',apikey:SUPABASE_KEY,Authorization:'Bearer '+s.access_token},body:JSON.stringify({conversation_id:data.id,message})});const result=await response.json();if(!response.ok)throw new Error(result.error||'AI analysis failed');workspaceLastAnswer=result.answer||result.reply||'';$('#workspaceAnswer').textContent=workspaceLastAnswer;$('#workspaceCreateText').value=workspaceLastAnswer;const {error:up}=await supabase.from('iyanda_workspace_files').update({ai_summary:workspaceLastAnswer.slice(0,12000),updated_at:new Date().toISOString()}).eq('id',f.id).eq('user_id',user.id);if(up)console.warn(up);await workspaceLoad();toast('Document analysis complete.')}catch(err){$('#workspaceAnswer').textContent='Could not analyse: '+err.message;toast(err.message)}finally{btn.disabled=false;btn.textContent='Analyse with Iyanda AI'}});
$('#workspaceSaveAnswer').addEventListener('click',async()=>{const value=$('#workspaceAnswer').textContent;if(!value){toast('There is no report to save yet.');return}$('#workspaceCreateText').value=value;await savedWorkSave('AI report: '+(workspaceSelected?.file_name||'Document'),value,'report',{source:'workspace'});workspaceDownload('Iyanda-AI-Report.txt',value,'text/plain;charset=utf-8')});
$('#workspaceSaveDraft').addEventListener('click',async()=>{const value=$('#workspaceCreateText').value.trim();if(!value){toast('Add some content before saving.');return}await savedWorkSave('Workspace draft',value,'document',{source:'workspace'})});
function workspaceDownload(name,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.querySelector('.workspace-tools').addEventListener('click',async e=>{const b=e.target.closest('[data-workspace-export]');if(!b)return;const content=$('#workspaceCreateText').value.trim();if(!content){toast('Add some content first.');return}const kind=b.dataset.workspaceExport;const lines=content.split(/\r?\n/).filter(x=>x.trim());const base='Iyanda-Workspace-'+new Date().toISOString().slice(0,10);try{if(kind==='txt'){workspaceDownload(base+'.txt',content,'text/plain;charset=utf-8')}else if(kind==='csv'){const csv=lines.map(x=>x.split(',').map(v=>'"'+v.trim().replace(/"/g,'""')+'"').join(',')).join('\r\n');workspaceDownload(base+'.csv','Content\r\n'+csv,'text/csv;charset=utf-8')}else if(kind==='xlsx'){const XLSX=await import('https://esm.sh/xlsx@0.18.5');const wb=XLSX.utils.book_new();const ws=XLSX.utils.aoa_to_sheet([['Content'],...lines.map(x=>[x])]);XLSX.utils.book_append_sheet(wb,ws,'Iyanda Report');XLSX.writeFile(wb,base+'.xlsx')}else if(kind==='docx'){const {Document,Packer,Paragraph,HeadingLevel}=await import('https://esm.sh/docx@8.5.0');const doc=new Document({sections:[{children:lines.map((x,i)=>new Paragraph({text:x,heading:i===0?HeadingLevel.HEADING_1:undefined}))}]});const blob=await Packer.toBlob(doc);const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=base+'.docx';a.click();URL.revokeObjectURL(url)}else if(kind==='pptx'){const {default:pptxgen}=await import('https://esm.sh/pptxgenjs@3.12.0');const pptx=new pptxgen();pptx.layout='LAYOUT_WIDE';pptx.author='Iyanda One';pptx.subject='Iyanda Workspace presentation';for(let i=0;i<lines.length;i+=5){const slide=pptx.addSlide();slide.addText(i===0?'Iyanda Workspace': 'Key points',{x:.5,y:.3,w:12,h:.6,fontSize:26,bold:true,color:'123D2B'});slide.addText(lines.slice(i,i+5).map(x=>'• '+x).join('\n'),{x:.7,y:1.3,w:11.7,h:5.3,fontSize:19,breakLine:false,bullet:{indent:18}})}await pptx.writeFile({fileName:base+'.pptx'})}toast('Your file has been generated.')}catch(err){toast('Could not create file: '+err.message)}});


/* Iyanda Creative Studio */
let creativeTab='music',creativeLastText='',creativeMusicRows=[];
function creativeSwitch(tab){creativeTab=tab;document.querySelectorAll('[data-creative-tab]').forEach(b=>b.classList.toggle('active',b.dataset.creativeTab===tab));['music','writing','visual','video'].forEach(k=>$('#creative'+k[0].toUpperCase()+k.slice(1)+'Form').classList.toggle('hidden',k!==tab));$('#creativeResult').textContent=tab==='music'?'Describe a sound and generate an original track.':'Your '+(tab==='writing'?'creative writing':tab==='visual'?'image prompt':'video storyboard')+' will appear here.';creativeLastText=''}
async function creativeLoad(){if(!user){$('#creativeSignIn').classList.remove('hidden');$('#creativeMain').classList.add('hidden');return}$('#creativeSignIn').classList.add('hidden');$('#creativeMain').classList.remove('hidden');await creativeLoadMusic()}
async function creativeLoadMusic(){if(!user)return;const {data,error}=await supabase.from('music_generations').select('id,prompt,model,storage_path,mime_type,description,created_at').eq('user_id',user.id).order('created_at',{ascending:false}).limit(30);if(error){$('#creativeMusicLibrary').innerHTML='<div class="daily-empty">Music library unavailable: '+esc(error.message)+'</div>';return}creativeMusicRows=data||[];$('#creativeMusicLibrary').innerHTML=creativeMusicRows.length?creativeMusicRows.map(t=>'<div class="creative-track"><b>'+esc(t.prompt.slice(0,120))+'</b><small>'+esc(t.model)+' · '+new Date(t.created_at).toLocaleString()+'</small>'+(t.description?'<small>'+esc(t.description)+'</small>':'')+'<div class="workspace-actions" style="margin-top:8px"><button class="btn light small" data-creative-play="'+t.id+'" type="button">Play track</button><button class="btn light small" data-creative-delete="'+t.id+'" type="button">Delete</button></div><div id="creativeAudio_'+t.id+'"></div></div>').join(''):'<div class="daily-empty">No saved music yet. Create your first track above.</div>'}
$('#creativeSignInBtn').addEventListener('click',openAuth);
$('#creativeTabs').addEventListener('click',e=>{const b=e.target.closest('[data-creative-tab]');if(b)creativeSwitch(b.dataset.creativeTab)});
$('#creativeRefreshMusic').addEventListener('click',creativeLoadMusic);
async function creativeAI(type,prompt){if(!user){openAuth();throw new Error('Sign in first.')}let cid;const {data,error}=await supabase.from('ai_conversations').insert({user_id:user.id,title:'Creative Studio: '+type}).select('id').single();if(error)throw error;cid=data.id;const message='You are helping in Iyanda Creative Studio. Create original, polished material. Task: '+type+'. User brief: '+prompt+'. Follow copyright rules: do not imitate a living artist or reproduce copyrighted lyrics; offer an original work using broad genre traits.';const {error:me}=await supabase.from('ai_messages').insert({conversation_id:cid,user_id:user.id,role:'user',content:message});if(me)throw me;const {data:{session:s}}=await supabase.auth.getSession();const res=await fetch(SUPABASE_URL+'/functions/v1/iyanda-ai',{method:'POST',headers:{'Content-Type':'application/json',apikey:SUPABASE_KEY,Authorization:'Bearer '+s.access_token},body:JSON.stringify({conversation_id:cid,message})});const out=await res.json();if(!res.ok)throw new Error(out.error||'Creative AI request failed');return out.answer}
async function creativeRunAI(type,prompt,button){if(!prompt.trim()){toast('Please describe what you want to create.');return}button.disabled=true;const old=button.textContent;button.textContent='Creating…';$('#creativeResult').textContent='Iyanda AI is working on your creation…';try{creativeLastText=await creativeAI(type,prompt);$('#creativeResult').textContent=creativeLastText;$('#creativeSaveStatus').textContent='Creation ready. Use Copy or Download to keep it.'}catch(e){$('#creativeResult').textContent='Could not create this yet: '+e.message;toast(e.message)}finally{button.disabled=false;button.textContent=old}}
$('#creativeGenerateWriting').addEventListener('click',e=>creativeRunAI($('#creativeWritingType').value,$('#creativeWritingPrompt').value,e.currentTarget));
$('#creativeGenerateVisual').addEventListener('click',e=>creativeRunAI('Write a detailed image-generation prompt in the '+$('#creativeVisualStyle').value+' style. Include subject, environment, lighting, composition, colour palette, camera and negative prompt. Return only the usable prompt.',$('#creativeVisualPrompt').value,e.currentTarget));
$('#creativeGenerateVideo').addEventListener('click',e=>creativeRunAI('Create a production-ready short video storyboard for '+$('#creativeVideoFormat').value+'. Include duration, timed scenes, camera movement, on-screen text, voiceover, sound design and transitions.',$('#creativeVideoPrompt').value,e.currentTarget));

function creativeAudioPlayer(container,src,label){container.innerHTML='<b>🎵 '+esc(label)+'</b><p class="muted">Your original audio track is ready. Tap Play sound to listen.</p><audio controls preload="metadata" playsinline style="display:block;width:100%;min-width:0;margin:12px 0" src="'+src+'"></audio><div class="workspace-actions"><button type="button" class="btn" data-creative-play-sound>▶ Play sound</button><a class="btn light small" href="'+src+'" download="Iyanda-generated-music.mp3">Download audio</a></div>';const audio=container.querySelector('audio');container.querySelector('[data-creative-play-sound]').addEventListener('click',async()=>{try{await audio.play()}catch(err){toast('Playback blocked by your browser. Use the Play button on the audio player.')}});audio.addEventListener('error',()=>{toast('This audio file could not be decoded by your browser. Try downloading it.')})}
$('#creativeGenerateMusic').addEventListener('click',async e=>{const btn=e.currentTarget,prompt=$('#creativeMusicPrompt').value.trim();if(!prompt){toast('Describe the music first.');return}if(!user){openAuth();return}btn.disabled=true;btn.textContent='Generating music…';$('#creativeResult').textContent='Generating your original audio. Please wait…';try{const {data:{session:s}}=await supabase.auth.getSession();if(!s)throw new Error('Please sign in again.');const res=await fetch(SUPABASE_URL+'/functions/v1/iyanda-music',{method:'POST',headers:{'Content-Type':'application/json',apikey:SUPABASE_KEY,Authorization:'Bearer '+s.access_token},body:JSON.stringify({prompt,duration:$('#creativeMusicDuration').value,instrumental:$('#creativeInstrumental').checked})});const out=await res.json();if(!res.ok)throw new Error(out.error+(out.detail?' — '+out.detail:''));if(!out.audio_base64)throw new Error('The music service returned no audio data. Please try again.');let encoded=out.audio_base64;if(encoded.includes(','))encoded=encoded.split(',').pop();const raw=atob(encoded);const bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);const mime=out.mime_type||'audio/mpeg';const blob=new Blob([bytes],{type:mime});if(blob.size<1000)throw new Error('The generated audio file is unexpectedly small and cannot be played.');const ext=mime.includes('wav')?'wav':mime.includes('ogg')?'ogg':'mp3';const path=user.id+'/'+crypto.randomUUID()+'.'+ext;const {error:uploadError}=await supabase.storage.from('iyanda-music').upload(path,blob,{contentType:mime,upsert:false});if(uploadError)throw new Error('Audio was generated but could not be saved: '+uploadError.message);const {error:dbError}=await supabase.from('music_generations').insert({user_id:user.id,prompt,model:out.model,storage_path:path,mime_type:mime,description:out.description||null});if(dbError){await supabase.storage.from('iyanda-music').remove([path]);throw new Error('Audio was generated but library save failed: '+dbError.message)}const {data:signed,error:signedError}=await supabase.storage.from('iyanda-music').createSignedUrl(path,3600);if(signedError)throw new Error('Track saved, but the audio player link could not be created: '+signedError.message);creativeLastText=out.description||'Original music generated from: '+prompt;creativeAudioPlayer($('#creativeResult'),signed.signedUrl,prompt);$('#creativeSaveStatus').textContent='Audio file saved privately. Use Play sound or the audio controls to listen.';await creativeLoadMusic();toast('Your music has been generated. Tap Play sound to listen.')}catch(err){$('#creativeResult').textContent='Music generation failed: '+err.message;toast(err.message)}finally{btn.disabled=false;btn.textContent='Generate music'}});
$('#creativeMusicLibrary').addEventListener('click',async e=>{const play=e.target.closest('[data-creative-play]');if(play){const t=creativeMusicRows.find(x=>x.id===play.dataset.creativePlay);if(!t)return;const {data,error}=await supabase.storage.from('iyanda-music').createSignedUrl(t.storage_path,3600);if(error){toast(error.message);return}const target=$('#creativeAudio_'+t.id);target.innerHTML='<audio controls preload="metadata" playsinline style="display:block;width:100%;margin-top:8px" src="'+data.signedUrl+'"></audio><button type="button" class="btn small" data-creative-play-sound>▶ Play sound</button>';const audio=target.querySelector('audio');target.querySelector('[data-creative-play-sound]').addEventListener('click',async()=>{try{await audio.play()}catch{toast('Use the Play button on the audio controls.')}});audio.addEventListener('error',()=>toast('This saved audio could not be decoded. Try downloading it.'));return}const del=e.target.closest('[data-creative-delete]');if(del){if(!confirm('Delete this generated track?'))return;const t=creativeMusicRows.find(x=>x.id===del.dataset.creativeDelete);if(!t)return;const {error}=await supabase.storage.from('iyanda-music').remove([t.storage_path]);if(error){toast(error.message);return}const {error:de}=await supabase.from('music_generations').delete().eq('id',t.id).eq('user_id',user.id);if(de){toast(de.message);return}await creativeLoadMusic();toast('Track deleted.')}});
$('#creativeSaveWork').addEventListener('click',async()=>{if(!creativeLastText){toast('Create some text or music first.');return}await savedWorkSave('Creative Studio creation',creativeLastText,'creative',{source:'creative-studio',tab:creativeTab})});
$('#creativeCopy').addEventListener('click',async()=>{if(!creativeLastText){toast('There is no text result to copy.');return}try{await navigator.clipboard.writeText(creativeLastText);toast('Copied.')}catch{toast('Copy is unavailable in this browser.')}});
$('#creativeDownload').addEventListener('click',()=>{if(!creativeLastText){toast('There is no text result to download.');return}const blob=new Blob([creativeLastText],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Iyanda-Creative-Studio.txt';a.click();URL.revokeObjectURL(url)});

/* Iyanda Saved Work — private, cross-session library */
let savedWorkRows=[];
async function savedWorkLoad(){
 if(!user){const list=$('#savedWorkList');if(list)list.innerHTML='<div class="daily-empty">Sign in to view your private saved work.</div>';return}
 const list=$('#savedWorkList');if(!list)return;
 const {data,error}=await supabase.from('iyanda_saved_work').select('id,title,work_type,content,metadata,created_at,updated_at').eq('user_id',user.id).order('updated_at',{ascending:false}).limit(100);
 if(error){list.innerHTML='<div class="daily-empty">Saved work could not load: '+esc(error.message)+'</div>';return}
 savedWorkRows=data||[];
 list.innerHTML=savedWorkRows.length?savedWorkRows.map(w=>'<div class="workspace-file"><div><b>'+esc(w.title)+'</b><small>'+esc(w.work_type)+' · '+new Date(w.updated_at).toLocaleString()+' · '+w.content.length.toLocaleString()+' characters</small></div><div class="workspace-actions"><button class="btn light small" type="button" data-saved-open="'+w.id+'">Open</button><button class="iconbtn" type="button" data-saved-delete="'+w.id+'" aria-label="Delete saved work">Delete</button></div></div>').join(''):'<div class="daily-empty">Nothing saved yet. Save a report, draft, creative result or language lesson to keep it here.</div>';
}
async function savedWorkSave(title,content,type='note',metadata={}){
 if(!user){openAuth();return false}
 const clean=String(content||'').trim();if(!clean){toast('There is no content to save.');return false}
 if(clean.length>200000){toast('This item is too large to save. Please shorten it.');return false}
 const {error}=await supabase.from('iyanda_saved_work').insert({user_id:user.id,title:String(title||'Saved work').slice(0,180),work_type:type,content:clean,metadata});
 if(error){toast('Could not save your work: '+error.message);return false}
 toast('Saved to My Saved Work.');await savedWorkLoad();return true;
}
const savedWorkList=$('#savedWorkList');if(savedWorkList)savedWorkList.addEventListener('click',async e=>{
 const open=e.target.closest('[data-saved-open]');if(open){const item=savedWorkRows.find(x=>x.id===open.dataset.savedOpen);if(!item)return;$('#workspaceCreateText').value=item.content;$('#workspaceAnswer').style.display='block';$('#workspaceAnswer').textContent=item.content;workspaceLastAnswer=item.content;location.hash='#/workspace';toast('Saved work opened in My Workspace.');return}
 const del=e.target.closest('[data-saved-delete]');if(del){const item=savedWorkRows.find(x=>x.id===del.dataset.savedDelete);if(!item||!confirm('Delete this saved item permanently?'))return;const {error}=await supabase.from('iyanda_saved_work').delete().eq('id',item.id).eq('user_id',user.id);if(error){toast(error.message);return}await savedWorkLoad();toast('Saved item deleted.')}
});
$('#savedWorkRefresh')?.addEventListener('click',savedWorkLoad);

